mod config;mod engine;mod events;mod execution;mod flow;mod market;mod persistence;mod portfolio;mod pumpportal;mod raydium;mod rpc;mod risk;mod security;mod strategy;
use config::AppConfig;use rpc::SolanaRpc;use std::time::Duration;use tokio::time::interval;use tracing::{error,info,warn};
#[tokio::main]async fn main(){tracing_subscriber::fmt().with_env_filter(std::env::var("RUST_LOG").unwrap_or_else(|_|"info,solana_trading_engine=debug".into())).init();let config=AppConfig::from_env();info!(mode=?config.mode,"Solana trading engine starting");if config.mode.allows_broadcast(){warn!("live mode is configured but broadcast remains hard-locked until production verification");}else{info!("live broadcast locked; paper/observe path active")}let rpc=SolanaRpc::new(config.rpc_url.clone());let store=persistence::SupabaseStore::from_env();match rpc.get_slot().await{Ok(slot)=>{info!(slot,"RPC healthy");if let Some(db)=&store{let _=db.health("rpc","healthy",None).await;}},Err(e)=>{error!(%e,"RPC health check failed");if let Some(db)=&store{let _=db.health("rpc","degraded",None).await;}}}match rpc.get_latest_blockhash().await{Ok(h)=>info!(blockhash=%h.blockhash,last_valid_block_height=h.last_valid_block_height,"blockhash check passed"),Err(e)=>error!(%e,"blockhash check failed")}let url=config.pumpportal_url.clone();let observer_rpc=rpc.clone();let observer_store=store.clone();tokio::spawn(async move{if let Err(e)=pumpportal::observe_new_tokens(&url,observer_rpc,observer_store).await{error!(%e,"market observer stopped")}});let mut tick=interval(Duration::from_secs(15));loop{tokio::select!{_=tick.tick()=>match rpc.get_slot().await{Ok(slot)=>{info!(slot,mode=?config.mode,"engine heartbeat");if let Some(db)=&store{let _=db.health("rust-engine","healthy",None).await;}},Err(e)=>error!(%e,"RPC heartbeat failed")},_=tokio::signal::ctrl_c()=>{info!("shutdown");break}}}}